def transform(grid):
    h, w = len(grid), len(grid[0])
    objects = []

    # Find 3x3 symbols: matching arms, with either matching or empty corners.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            frame = grid[r - 1][c]
            center = grid[r][c]
            if frame == 0 or center == 0:
                continue
            if (grid[r + 1][c] != frame or grid[r][c - 1] != frame
                    or grid[r][c + 1] != frame):
                continue

            corners = [grid[r - 1][c - 1], grid[r - 1][c + 1],
                       grid[r + 1][c - 1], grid[r + 1][c + 1]]
            ring = all(x == frame for x in corners)
            plus = all(x == 0 for x in corners)
            if not (ring or plus):
                continue

            cells = [(r, c), (r - 1, c), (r + 1, c),
                     (r, c - 1), (r, c + 1)]
            if ring:
                cells.extend([(r - 1, c - 1), (r - 1, c + 1),
                              (r + 1, c - 1), (r + 1, c + 1)])
            objects.append((r, c, frame, center, cells))

    # A symbol points to the symbol whose frame color matches its center.
    by_frame = {}
    for i, obj in enumerate(objects):
        by_frame.setdefault(obj[2], []).append(i)

    edges = {}
    for i, obj in enumerate(objects):
        targets = [j for j in by_frame.get(obj[3], []) if j != i]
        if targets:
            edges[i] = targets[0]

    out = [row[:] for row in grid]
    for obj in objects:
        for r, c in obj[4]:
            out[r][c] = 0

    indegree = [0] * len(objects)
    for target in edges.values():
        indegree[target] += 1

    visited = set()
    for start in range(len(objects)):
        if indegree[start] != 0 or start in visited:
            continue

        chain = []
        i = start
        while i not in visited:
            visited.add(i)
            chain.append(i)
            if i not in edges:
                break
            i = edges[i]

        # Keep every other symbol in the chain, leaving its terminal removed.
        for k in range(0, len(chain) - 1, 2):
            obj = objects[chain[k]]
            next_obj = objects[chain[k + 1]]
            for r, c in obj[4]:
                out[r][c] = obj[2]
            out[obj[0]][obj[1]] = next_obj[3]

    return out
